text:
1.9 Comparar modelos: sesgo, sobreajuste y validación cruzada
Como varios modelos pueden representar la misma realidad, necesitamos compararlos. En este libro, el mejor modelo es, por defecto, el que mejor representa la realidad que pretende aproximar para el propósito en cuestión, y lo medimos con métricas de rendimiento calculadas con datos que el modelo no ha visto (James et al. 2021, cap. 2). En el aprendizaje supervisado, las métricas miden la distancia entre las predicciones y los desenlaces observados (error absoluto medio, exactitud, área bajo la curva ROC…); en el aprendizaje no supervisado, miden lo bien que se capta la estructura (silueta, error de reconstrucción); en el aprendizaje por refuerzo, la recompensa acumulada; en el modelado generativo, la fidelidad, la diversidad y la seguridad de lo generado. Cada capítulo presenta las métricas que necesita. El rendimiento predictivo no es el único criterio: también valoramos los modelos que pueden interpretarse y usarse para responder preguntas científicas (Capítulo 12), y un buen análisis busca un equilibrio.

Definición 1.8 (Sesgo, varianza, sobreajuste) Un modelo tiene un sesgo alto cuando sus supuestos son demasiado rígidos para captar el patrón real: se subajusta (underfitting) y se equivoca de forma sistemática. Tiene una varianza alta cuando es tan flexible que sigue el ruido de su conjunto de entrenamiento concreto: se sobreajusta (overfitting), con un rendimiento excelente en el entrenamiento y pobre con datos nuevos. Los buenos modelos equilibran ambos (James et al. 2021, cap. 2).







Figura 1.9: Un sillón moldeado para adaptarse perfectamente a un solo niño. Es ideal para ese niño e incómodo, o inútil, para cualquier otro: un modelo sobreajustado está hecho a la medida de sus datos de entrenamiento de la misma manera.



Piensa en un sillón hecho a medida para un niño (Figura 1.9): se ajusta a cada curva de ese niño, y de nadie más. Un modelo sobreajustado se ha moldeado en torno a los pacientes concretos con los que se entrenó, incluidas sus peculiaridades accidentales, y se ajusta mal a los pacientes nuevos.

Demasiado simple, justo, demasiado flexible. Treinta puntos de entrenamiento proceden de una curva suave (discontinua) más ruido. El modelo es un polinomio cuyo grado eliges tú: el grado 1 es una recta; los grados altos se curvan muchas veces. Observa el error de entrenamiento y el error en 300 puntos de prueba nuevos.

viewof deg = Inputs.range([0, 15], {value: 1, step: 1, label: "Grado del polinomio"})







ofit = {
  function mulberry32(a) { return function() { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a &gt;&gt;&gt; 15, 1 | a); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; }; }
  const rnd = mulberry32(42);
  const gauss = () =&gt; { let u = 0, v = 0; while (u === 0) u = rnd(); v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  const truth = x =&gt; Math.sin(3 * x) + 0.3 * x;
  const sample = m =&gt; d3.range(m).map(() =&gt; { const x = rnd() * 2 - 1; return {x, y: truth(x) + 0.35 * gauss()}; });
  const train = sample(30), test = sample(300);
  const cheb = (x, d) =&gt; { const T = [1, x]; for (let k = 2; k &lt;= d; k++) T.push(2 * x * T[k - 1] - T[k - 2]); return T.slice(0, d + 1); };
  function fit(d) {
    const m = d + 1, A = d3.range(m).map(() =&gt; new Array(m).fill(0)), bv = new Array(m).fill(0);
    for (const p of train) { const t = cheb(p.x, d); for (let i = 0; i &lt; m; i++) { bv[i] += t[i] * p.y; for (let j = 0; j &lt; m; j++) A[i][j] += t[i] * t[j]; } }
    for (let i = 0; i &lt; m; i++) A[i][i] += 1e-9;
    for (let c = 0; c &lt; m; c++) { let piv = c; for (let r = c + 1; r &lt; m; r++) if (Math.abs(A[r][c]) &gt; Math.abs(A[piv][c])) piv = r;
      [A[c], A[piv]] = [A[piv], A[c]]; [bv[c], bv[piv]] = [bv[piv], bv[c]];
      for (let r = 0; r &lt; m; r++) if (r !== c) { const f = A[r][c] / A[c][c]; for (let k = c; k &lt; m; k++) A[r][k] -= f * A[c][k]; bv[r] -= f * bv[c]; } }
    const w = bv.map((v, i) =&gt; v / A[i][i]);
    const pred = x =&gt; cheb(x, d).reduce((s, t, i) =&gt; s + t * w[i], 0);
    const rmse = data =&gt; Math.sqrt(d3.mean(data, p =&gt; (p.y - pred(p.x)) ** 2));
    return {pred, train: rmse(train), test: rmse(test)};
  }
  const all = d3.range(0, 16).map(d =&gt; ({d, ...fit(d)}));
  return {train, truth, all};
}







{
  const cur = ofit.all[deg];
  const grid = d3.range(-1, 1.0001, 0.01);
  const verdict = deg &lt;= 2 ? "sesgo alto: demasiado simple para seguir la curva" : deg &lt;= 6 ? "un equilibrio razonable" : "varianza alta: persigue el ruido";
  return html`&lt;p&gt;Grado ${deg}: error de entrenamiento &lt;strong&gt;${cur.train.toFixed(3)}&lt;/strong&gt; · error de prueba &lt;strong&gt;${cur.test.toFixed(3)}&lt;/strong&gt;: ${verdict}.&lt;/p&gt;`;
}







Plot.plot({
  height: 260, grid: true, y: {domain: [-2.5, 2.5], label: "y"}, x: {label: "x"},
  marks: [
    Plot.line(d3.range(-1, 1.0001, 0.01).map(x =&gt; [x, ofit.truth(x)]), {strokeDasharray: "5,4"}),
    Plot.line(d3.range(-1, 1.0001, 0.005).map(x =&gt; [x, Math.max(-2.5, Math.min(2.5, ofit.all[deg].pred(x)))]), {stroke: "#1f6f8b", strokeWidth: 2.5}),
    Plot.dot(ofit.train, {x: "x", y: "y", r: 3, fill: "currentColor"})
  ]
})







Plot.plot({
  height: 200, grid: true, x: {label: "Grado del polinomio"}, y: {label: "Error (RMSE)", domain: [0, 1.2]},
  color: {legend: true, domain: ["entrenamiento", "prueba"], range: ["#888", "#1f6f8b"]},
  marks: [
    Plot.line(ofit.all, {x: "d", y: d =&gt; Math.min(d.train, 1.2), stroke: () =&gt; "entrenamiento", strokeWidth: 2}),
    Plot.line(ofit.all, {x: "d", y: d =&gt; Math.min(d.test, 1.2), stroke: () =&gt; "prueba", strokeWidth: 2}),
    Plot.ruleX([deg], {strokeDasharray: "3,3"})
  ]
})







El error de entrenamiento siempre baja a medida que el modelo se vuelve más flexible; el error de prueba baja y luego vuelve a subir. El grado con el menor error de prueba es el que hay que elegir. Pero hemos usado el conjunto de prueba para tomar esa decisión, así que ya no es un juez honesto del modelo elegido. El remedio habitual es la validación cruzada.

Definición 1.9 (Validación cruzada) En la validación cruzada con \(V\) particiones (\(V\)-fold), los datos de entrenamiento se dividen en \(V\) partes (particiones). Cada partición, por turno, se deja fuera mientras el modelo se ajusta con las otras \(V-1\) particiones y se evalúa con la que se ha apartado; después se promedian los \(V\) errores. Las elecciones como el grado del polinomio se hacen con el error de validación cruzada, y el conjunto de prueba se usa una sola vez, al final. Con \(V = n\) se llama validación cruzada leave-one-out (dejando uno fuera) (Stone 1974; James et al. 2021, cap. 5).



  Validación cruzada con cinco particiones
  Cinco filas, una por ronda. En cada fila, los datos de entrenamiento se dibujan como cinco bloques; en cada fila se aparta un bloque distinto para la validación y los otros cuatro se usan para el ajuste.

  Ronda 1Ronda 2Ronda 3Ronda 4Ronda 5








  apartada

Validación cruzada con cinco particiones: cada partición (resaltada) se aparta una vez mientras el modelo se ajusta con las otras cuatro.

Sesgo, sobreajuste y validación cruzada abordan una misma pregunta: ¿está el modelo aprendiendo la señal o memorizando el ruido? Responderla con honestidad es lo que hace que un modelo sirva para fundamentar decisiones reales. El Capítulo 3 convierte estas ideas en una rutina de trabajo.

Tu primera evaluación honesta. Usa la división fija del libro de los datos de la UCI Sala 7 en un conjunto de entrenamiento (1000 pacientes, 80 %) y uno de prueba (250 pacientes, 20 %) y evalúa después el modelo más sencillo posible: predecir, para cada paciente de prueba, el cambio medio de la creatinina de los pacientes de entrenamiento. Rellena el hueco con la función que calcula una media. La última línea calcula el error absoluto medio en el conjunto de prueba.

RPython

















La función que calcula la media aritmética en R es mean().


prediction &lt;- mean(train$delta_creatinine_48h)


















Las columnas de pandas tienen un método .mean().


prediction = train["delta_creatinine_48h"].mean()




R y Python leen la misma división, así que ambos dan 0,236 mg/dL. Esta es la primera fila de la tabla de comparación que inicia el Capítulo 3 y que amplían todos los capítulos posteriores: cada nuevo modelo de la UCI Sala 7 se juzga con estos mismos 250 pacientes de prueba.

3.5 La validación cruzada, paso a paso
El Capítulo 1 definió la validación cruzada con \(V\) particiones (Definición 1.9); este es el procedimiento completo (Stone 1974; James et al. 2021, cap. 5). Toma el conjunto de entrenamiento, ya dividido en \(V\) particiones de tamaño aproximadamente igual (en la UCI Sala 7, \(V = 5\) particiones de 200). Después, para cada partición \(v = 1, \dots, V\):

aparta la partición \(v\) como partición de validación;
ajusta el modelo en las otras \(V - 1\) particiones, incluido cada paso que dependa de los datos (elegir variables, estandarizar, imputar; consulta la Sección 3.6);
predice los desenlaces de la partición de validación y calcula la métrica, \(\text{MAE}_v\).

Por último, promedia los \(V\) resultados:
\[
\text{CV}_{(V)} = \frac{1}{V}\sum_{v=1}^{V} \text{MAE}_v .
\qquad(3.6)\]
Cada paciente de entrenamiento se usa para validar exactamente una vez y para ajustar \(V - 1\) veces. La dispersión de los \(V\) errores de las particiones indica cuánto se movería la estimación con otra división; su error estándar, la desviación típica de los errores de las particiones dividida por \(\sqrt{V}\), es una medida aproximada de esa incertidumbre (Hastie, Tibshirani, y Friedman 2009, cap. 7).

Mira cómo ocurre la validación cruzada. Cada punto es uno de los 1000 pacientes de entrenamiento de la UCI Sala 7. En cada ronda se aparta una partición (en color), el modelo se ajusta en las otras cuatro (en gris) y su MAE se calcula en la partición apartada. La ronda 6 combina los cinco resultados. Elige un modelo y después pulsa Reproducir o mueve el control deslizante. Fíjate en que el conjunto de prueba nunca participa.

icu3 = FileAttachment("data/icu_aki.csv").csv({typed: true})
split3 = FileAttachment("data/splits/ward7_split.csv").csv({typed: true})
w7 = icu3.map((d, i) =&gt; ({...d, set: split3[i].set, fold: split3[i].fold,
                          sx: d.sofa + (((i * 7919) % 101) / 101 - 0.5) * 0.6}))
w7train = w7.filter(d =&gt; d.set === "train")
viewof cvModel = Inputs.radio(["Modelo de la media", "Recta en función del SOFA"], {value: "Modelo de la media", label: "Modelo"})
viewof cvPlay = Inputs.toggle({label: "Reproducir", value: false})
viewof cvManual = Inputs.range([1, 6], {value: 1, step: 1, label: "Ronda (6 = combinar)"})



















































cvRound = {
  if (!cvPlay) { yield cvManual; return; }
  let r = 0;
  while (true) { yield (r % 6) + 1; r += 1; await Promises.delay(1400); }
}
cvFits = {
  const fitFn = rows =&gt; {
    const ys = rows.map(d =&gt; d.delta_creatinine_48h), my = d3.mean(ys);
    if (cvModel === "Modelo de la media") return {a: my, b: 0};
    const xs = rows.map(d =&gt; d.sofa), mx = d3.mean(xs);
    const b = d3.sum(xs, (x, i) =&gt; (x - mx) * (ys[i] - my)) / d3.sum(xs, x =&gt; (x - mx) ** 2);
    return {a: my - b * mx, b};
  };
  return [1, 2, 3, 4, 5].map(v =&gt; {
    const f = fitFn(w7train.filter(d =&gt; d.fold !== v));
    const val = w7train.filter(d =&gt; d.fold === v);
    return {fold: v, a: f.a, b: f.b, mae: d3.mean(val, d =&gt; Math.abs(d.delta_creatinine_48h - (f.a + f.b * d.sofa)))};
  });
}
{
  const r = cvRound;
  const box = (label, sub, on, dashed) =&gt; html`&lt;div style="flex:1; min-width:58px; padding:6px 4px; text-align:center; border-radius:6px; font-size:0.82rem; border:1.5px ${dashed ? "dashed" : "solid"} ${on ? "var(--aihs-accent)" : "var(--aihs-border)"}; background:${on ? "var(--aihs-accent-soft)" : "transparent"}"&gt;&lt;strong&gt;${label}&lt;/strong&gt;&lt;br&gt;${sub}&lt;/div&gt;`;
  const cells = cvFits.map(f =&gt; box(`Partición ${f.fold}`,
    r === 6 ? `MAE ${f.mae.toFixed(3)}` : (r === f.fold ? "validación" : "ajuste"), r === f.fold || r === 6, false));
  const cv = d3.mean(cvFits, f =&gt; f.mae), se = d3.deviation(cvFits, f =&gt; f.mae) / Math.sqrt(5);
  if (r === 6 && window.aihs) window.aihs.complete("ch03-tryit-cv");
  return html`&lt;div style="display:flex; flex-wrap:wrap; gap:6px; margin:0.4rem 0"&gt;${cells}${box("Conjunto de prueba", "250 · bajo llave", false, true)}&lt;/div&gt;
  &lt;p&gt;${r &lt; 6
    ? html`Ronda ${r}: ajustado en las particiones ${[1, 2, 3, 4, 5].filter(v =&gt; v !== r).join(", ")}; MAE en la partición ${r} = &lt;strong&gt;${cvFits[r - 1].mae.toFixed(3)}&lt;/strong&gt; mg/dL.`
    : html`MAE de validación cruzada = media de las cinco = &lt;strong&gt;${cv.toFixed(3)}&lt;/strong&gt; mg/dL (error estándar ${se.toFixed(3)}).`}&lt;/p&gt;`;
}























{
  const r = cvRound, lines = r === 6 ? cvFits : [cvFits[r - 1]];
  return Plot.plot({
    height: 290, grid: true, color: {type: "identity"},
    x: {label: "Puntuación SOFA al ingreso", domain: [-0.5, 18.5]},
    y: {label: "Variación de la creatinina en 48 h (mg/dL)"},
    marks: [
      Plot.dot(w7train, {x: "sx", y: "delta_creatinine_48h", r: 1.8,
        fill: d =&gt; (r === 6 || d.fold === r) ? "#1f6f8b" : "#999",
        fillOpacity: d =&gt; (r === 6 || d.fold === r) ? 0.6 : 0.25}),
      ...lines.map(f =&gt; Plot.line([[0, f.a], [18, f.a + 18 * f.b]], {stroke: "#b35c00", strokeWidth: r === 6 ? 1.5 : 3}))
    ]
  });
}







Plot.plot({
  height: 170, grid: true, marginLeft: 50,
  x: {label: "Partición de validación", domain: [1, 2, 3, 4, 5], type: "band"},
  y: {label: "MAE (mg/dL)", domain: [0, 0.3]},
  marks: [
    Plot.barY(cvFits.filter(f =&gt; cvRound === 6 || f.fold &lt;= cvRound), {x: "fold", y: "mae", fill: "#1f6f8b", fillOpacity: 0.7}),
    cvRound === 6 ? Plot.ruleY([d3.mean(cvFits, f =&gt; f.mae)], {stroke: "#b35c00", strokeWidth: 2}) : null,
    Plot.ruleY([0])
  ]
})








Los cinco errores de las particiones no son idénticos; difieren hasta en unas centésimas de mg/dL, porque algunas particiones contienen por casualidad pacientes más fáciles que otras. Esa variación es precisamente la razón por la que una sola división puede engañar, y por la que promediar entre particiones da una estimación más estable.
¿Cuántas particiones? Con un \(V\) mayor, cada ajuste usa una parte mayor de los datos, así que la estimación se acerca más al error de un modelo entrenado con todos ellos; pero los ajustes se solapan más, los \(V\) errores se parecen más entre sí y el cálculo crece. La validación cruzada leave-one-out, dejando fuera una instancia cada vez (\(V = n\)), es el extremo: casi sin sesgo, pero variable y costosa para los modelos lentos. Cinco o diez particiones son el compromiso habitual (James et al. 2021, cap. 5; Hastie, Tibshirani, y Friedman 2009, cap. 7). Hay dos refinamientos frecuentes. La validación cruzada repetida vuelve a ejecutar todo el procedimiento con varias asignaciones aleatorias de las particiones y las promedia, lo que estabiliza todavía más la estimación. Las particiones estratificadas mantienen parecida en todas las particiones la proporción de un desenlace (por ejemplo, LRA sí/no) (Kuhn y Johnson 2013, cap. 4).
Las particiones deben respetar la estructura de los datos. Si un paciente aporta varias filas, como un participante de HomeBeat con una fila por día, todas las filas de esa persona deben estar en la misma partición; de lo contrario, el modelo se valida en parte con las mismas personas con las que se ajustó. La misma lógica, aplicada a los hospitales, da la validación cruzada dejando fuera un hospital (leave-one-site-out): ajustar en tres hospitales de la UCI Sala 7, probar en el cuarto y rotar. Es la validación interna-externa de la Sección 3.2, y la usamos al final de este capítulo.

Con validación cruzada con cinco particiones en los 1000 pacientes de entrenamiento de la UCI Sala 7, ¿cuántas veces se ajusta el modelo, y con cuántos pacientes cada vez?

Una vez, con 1000 pacientes Eso es un único ajuste en todo el conjunto de entrenamiento: da un modelo, pero ninguna estimación honesta del error.
Cinco veces, con 800 pacientes cada vez Correcto. Cada ronda deja fuera una partición de 200 y ajusta con los 800 restantes. (Una vez que la validación cruzada ha guiado las elecciones, el modelo elegido suele volver a ajustarse una vez más con los 1000.)
Cinco veces, con 200 pacientes cada vez Es al revés: cada ajuste usa cuatro particiones (800 pacientes) y se valida en la quinta (200).
1000 veces, con 999 pacientes cada vez Eso es la validación cruzada leave-one-out, el caso \(V = n\).

3.7 \(k\) vecinos más próximos: un primer método de aprendizaje
Hasta ahora, nuestros modelos han sido medias y rectas. Esta es una idea distinta, cercana a cómo razonan los clínicos a partir de la experiencia: para predecir qué le pasará a Aoife, mira a los pacientes anteriores que más se parecían a ella y fíjate en qué les pasó.

Definición 3.5 (\(k\) vecinos más próximos) El método de los \(k\) vecinos más próximos (\(k\)NN, del inglés \(k\)-nearest neighbours) predice el desenlace de una instancia nueva \(\mathbf{x}\) buscando las \(k\) instancias de entrenamiento más próximas a ella, el conjunto \(N_k(\mathbf{x})\), y promediando sus desenlaces (para un desenlace numérico) o haciendo una votación (para una categoría):
\[
\hat y(\mathbf{x}) = \frac{1}{k}\sum_{i \in N_k(\mathbf{x})} y_i .
\qquad(3.7)\]
“Más próximas” se mide con una distancia entre vectores de características, normalmente la distancia euclídea entre características estandarizadas (Cover y Hart 1967; James et al. 2021, cap. 2).

El \(k\)NN tiene una propiedad poco habitual: no tiene paso de ajuste. El “entrenamiento” consiste en guardar los pacientes de entrenamiento; todo el trabajo ocurre en el momento de la predicción. Dos ingredientes requieren cuidado.
Distancia. En la UCI Sala 7 usamos dos predictores, la puntuación SOFA y la creatinina basal, y medimos lo alejados que están dos pacientes con la distancia habitual en línea recta (euclídea) en el plano que forman los dos. El Capítulo 10 está dedicado a las distancias y a lo que les ocurre cuando hay muchos predictores; por ahora, el plano basta.
Escala. El SOFA va de 0 a 18 puntos; la creatinina basal, de unos 0,4 a 3 mg/dL. Medido en bruto, un punto de SOFA contaría tanto como un mg/dL entero de creatinina, solo por las unidades. Por eso cada predictor se estandariza: se resta la media del entrenamiento y el resultado se divide por la desviación típica del entrenamiento, lo que pone a ambos en una escala comparable. Con la estandarización, las predicciones no dependen de las unidades. Sin ella, sí: si la creatinina se registra en µmol/L (1 mg/dL = 88,4 µmol/L), sus números grandes dominan la distancia y el MAE de validación cruzada del \(k\)NN sin estandarizar empeora de 0,181 a 0,189 mg/dL, mientras que el \(k\)NN estandarizado da 0,179 en cualquiera de las dos unidades. Fíjate en la palabra entrenamiento: las medias y las desviaciones típicas se aprenden solo con las filas de entrenamiento (con las particiones de ajuste, durante la validación cruzada), o el propio escalado provoca una fuga (Sección 3.6).
El número de vecinos \(k\) controla la flexibilidad. Con \(k = 1\), cada predicción copia a un único paciente anterior: el modelo sigue cada accidente de los datos, el extremo de varianza alta de la Definición 1.8. Su error de entrenamiento es casi cero, porque cada paciente de entrenamiento es (casi) su propio vecino más próximo; en la UCI Sala 7 es de 0,072 mg/dL. Su error de validación cruzada es de 0,254, peor que el del modelo de la media. A medida que \(k\) crece, las predicciones se promedian sobre más pacientes y se vuelven más suaves; con \(k\) igual a todo el conjunto de entrenamiento, toda predicción es la media del entrenamiento, el extremo de sesgo alto. En algún punto intermedio está el mejor compromiso, y solo los datos que el modelo no ha visto pueden decirnos dónde.

Pacientes como Aoife. El fondo muestra la predicción del \(k\)NN de la variación de la creatinina en 48 horas para cada combinación de SOFA y creatinina basal; los puntos grises son los 1000 pacientes de entrenamiento y los tres puntos con nombre son los pacientes de esta noche. Los puntos rodeados con un círculo son los \(k\) vecinos más próximos de Aoife. El gráfico de abajo muestra el error de entrenamiento y el error de validación cruzada con cinco particiones para cada \(k\). Mueve \(k\) y observa cómo el mapa pasa de irregular a suave. Objetivo: encontrar un \(k\) cuyo MAE de validación cruzada quede a menos de 0,001 mg/dL del mínimo posible.

knnCurve = FileAttachment("data/precomputed/ch03/knn_curve.csv").csv({typed: true})
knnSummary = FileAttachment("data/precomputed/ch03/summary.json").json()
tonight3 = FileAttachment("data/ward7_tonight.csv").csv({typed: true})
viewof kNN = Inputs.range([1, 150], {value: 1, step: 1, label: "Número de vecinos k"})






























knnPrep = {
  const tr = w7train, K = 150;
  const xs = tr.map(d =&gt; d.sofa), cs = tr.map(d =&gt; d.baseline_creat), ys = tr.map(d =&gt; d.delta_creatinine_48h);
  const mx = d3.mean(xs), sx = d3.deviation(xs), mc = d3.mean(cs), sc = d3.deviation(cs);
  const zx = xs.map(x =&gt; (x - mx) / sx), zc = cs.map(c =&gt; (c - mc) / sc);
  const neigh = (s, c) =&gt; {
    const a = (s - mx) / sx, b = (c - mc) / sc;
    const d = zx.map((z, i) =&gt; ({i, d: (z - a) ** 2 + (zc[i] - b) ** 2}));
    d.sort((p, q) =&gt; p.d - q.d || p.i - q.i);
    const cum = new Float64Array(K); let acc = 0;
    for (let j = 0; j &lt; K; j++) { acc += ys[d[j].i]; cum[j] = acc; }
    return {cum, idx: d.slice(0, K).map(e =&gt; e.i)};
  };
  const c0 = 0.4, c1 = 2.6, ny = 28, cs0 = (c1 - c0) / ny, grid = [];
  for (let s = 0; s &lt;= 18; s++) for (let b = 0; b &lt; ny; b++) {
    const c = c0 + (b + 0.5) * cs0;
    grid.push({x1: s - 0.5, x2: s + 0.5, y1: c0 + b * cs0, y2: c0 + (b + 1) * cs0, cum: neigh(s, c).cum});
  }
  const pts = tonight3.map(p =&gt; ({name: p.name.split(" ")[0], sofa: p.sofa, creat: p.baseline_creat, ...neigh(p.sofa, p.baseline_creat)}));
  const jit = tr.map((d, i) =&gt; ({sx: d.sofa + (((i * 7919) % 101) / 101 - 0.5) * 0.6, c: d.baseline_creat}));
  return {grid, pts, jit};
}







