ols4 = (X, y) =&gt; {
  // mínimos cuadrados mediante las ecuaciones normales (X'X) b = X'y, resueltas por eliminación de Gauss
  const p = X[0].length, A = Array.from({length: p}, () =&gt; new Array(p + 1).fill(0));
  X.forEach((row, i) =&gt; { for (let r = 0; r &lt; p; r++) { for (let c = 0; c &lt; p; c++) A[r][c] += row[r] * row[c]; A[r][p] += row[r] * y[i]; } });
  for (let c = 0; c &lt; p; c++) {
    let piv = c; for (let r = c + 1; r &lt; p; r++) if (Math.abs(A[r][c]) &gt; Math.abs(A[piv][c])) piv = r;
    [A[c], A[piv]] = [A[piv], A[c]];
    for (let r = 0; r &lt; p; r++) if (r !== c) { const f = A[r][c] / A[c][c]; for (let k = c; k &lt;= p; k++) A[r][k] -= f * A[c][k]; }
  }
  return A.map((row, r) =&gt; row[p] / row[r]);
}
