Mira cómo se concentran las distancias. Cien pacientes simulados se describen con \(p\) características. El histograma muestra las 4950 distancias entre pares, cada una dividida por su media, para que veas su dispersión y no su tamaño; el gráfico de abajo muestra el cociente entre la distancia más corta y la más larga para cada \(p\). Alterna entre características que son ruido independiente y características generadas por dos factores ocultos más ruido, como el bloque de genes de Dermato-ATT. Objetivo: con ruido independiente, encuentra el menor \(p\) en el que el par más cercano está al menos a la mitad de la distancia del par más lejano.

viewof concP = Inputs.range([1, 1000], {value: 2, step: 1, transform: Math.log, label: "Número de características p"})
viewof concKind = Inputs.radio(["ruido independiente", "dos factores ocultos + ruido"], {value: "ruido independiente", label: "Tipo de datos"})
















concSim = {
  function mulberry32(a) { return function() { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a &gt;&gt;&gt; 15, 1 | a); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; }; }
  const rnd = mulberry32(2026);
  const gauss = () =&gt; { let u = 0; while (u === 0) u = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rnd()); };
  const n = 100, P = 1000;
  const noise = d3.range(n).map(() =&gt; Float64Array.from({length: P}, gauss));
  const f1 = d3.range(n).map(gauss), f2 = d3.range(n).map(gauss);
  const a = Float64Array.from({length: P}, () =&gt; 0.7 + 0.2 * gauss()), b = Float64Array.from({length: P}, () =&gt; 0.7 + 0.2 * gauss());
  const factor = d3.range(n).map(i =&gt; Float64Array.from({length: P}, (_, j) =&gt; f1[i] * a[j] + f2[i] * b[j] + 0.5 * noise[i][j]));
  const checkpoints = [1, 2, 3, 5, 10, 20, 50, 100, 200, 500, 1000];
  function curve(X) {
    const out = [], acc = new Float64Array(n * (n - 1) / 2);
    let c = 0;
    for (let j = 0; j &lt; P; j++) {
      let k = 0;
      for (let i = 0; i &lt; n; i++) for (let l = i + 1; l &lt; n; l++) { const d = X[i][j] - X[l][j]; acc[k++] += d * d; }
      if (j + 1 === checkpoints[c]) { const s = Array.from(acc, Math.sqrt); out.push({p: j + 1, ratio: d3.min(s) / d3.max(s)}); c++; }
    }
    return out;
  }
  function at(X, p) {
    const d = [];
    for (let i = 0; i &lt; n; i++) for (let l = i + 1; l &lt; n; l++) { let s = 0; for (let j = 0; j &lt; p; j++) { const e = X[i][j] - X[l][j]; s += e * e; } d.push(Math.sqrt(s)); }
    return d;
  }
  return {noise, factor, at, curves: [...curve(noise).map(d =&gt; ({...d, kind: "ruido independiente"})), ...curve(factor).map(d =&gt; ({...d, kind: "dos factores ocultos + ruido"}))]};
}







concNow = {
  const X = concKind === "ruido independiente" ? concSim.noise : concSim.factor;
  const d = concSim.at(X, concP), m = d3.mean(d), mn = d3.min(d), mx = d3.max(d);
  return {rel: d.map(v =&gt; v / m), ratio: mn / mx, contrast: (mx - mn) / mn};
}
{
  const hit = concKind === "ruido independiente" && concNow.ratio &gt;= 0.5;
