  · contraste relativo (mayor − menor) / menor: &lt;strong&gt;${concNow.contrast.toFixed(2)}&lt;/strong&gt;
  ${hit ? " · ✓ Objetivo alcanzado: a medio camino de 'todos están igual de lejos'." : ""}&lt;/p&gt;`;
}
















