dendroLayout = {
  const n = dendro.labels.length, pos = new Array(n);
  dendro.order.forEach((leaf, i) =&gt; { pos[leaf - 1] = i; });
  const nodeX = [], nodeY = [], segs = [];
  const xy = m =&gt; m &lt; 0 ? [pos[-m - 1], 0] : [nodeX[m - 1], nodeY[m - 1]];
  dendro.merge.forEach(([a, b], i) =&gt; {
    const [xa, ya] = xy(a), [xb, yb] = xy(b), h = dendro.height[i];
    nodeX.push((xa + xb) / 2); nodeY.push(h);
    segs.push({x1: xa, y1: ya, x2: xa, y2: h}, {x1: xb, y1: yb, x2: xb, y2: h}, {x1: xa, y1: h, x2: xb, y2: h});
  });
  return {pos, segs};
}
cutRes = {
  const n = dendro.labels.length, parent = d3.range(n), leafOf = [];
  const find = i =&gt; parent[i] === i ? i : (parent[i] = find(parent[i]));
  const leaf = m =&gt; m &lt; 0 ? -m - 1 : leafOf[m - 1];
  dendro.merge.forEach(([a, b], i) =&gt; {
    leafOf.push(leaf(a));
    if (dendro.height[i] &lt;= cutH) parent[find(leaf(b))] = find(leaf(a));
  });
  const roots = d3.range(n).map(find), ids = new Map();
  dendro.order.forEach(l =&gt; { const r = roots[l - 1]; if (!ids.has(r)) ids.set(r, ids.size + 1); });
  const cl = roots.map(r =&gt; ids.get(r));
  return {cl, K: ids.size, ari: ariJS(cl, dendro.subtype)};
}






























