wiFeats = ["sofa", "lactate", "map_min", "baseline_creat", "protocol_adherence"]
wiAoife = ({sofa: 6, lactate: 2.1, map_min: 66, baseline_creat: 1.0, protocol_adherence: 0.72})
wiMeans = {
  const tr = new Set(split12.filter(d =&gt; d.set === "train").map(d =&gt; d.patient_id));
  const rows = icu12.filter(d =&gt; tr.has(d.patient_id));
  return Object.fromEntries(wiFeats.map(f =&gt; [f, d3.mean(rows, d =&gt; d[f])]));
}
wiBeta = Object.fromEntries(coefs12.map(d =&gt; [d.term, d.estimate]))
viewof wSofa = Inputs.range([0, 18], {value: 6, step: 1, label: "Puntuación SOFA"})
viewof wLact = Inputs.range([0.5, 8], {value: 2.1, step: 0.1, label: "Lactato (mmol/L)"})
viewof wCreat = Inputs.range([0.4, 2.5], {value: 1.0, step: 0.05, label: "Creatinina basal (mg/dL)"})
viewof wMap = Inputs.range([40, 100], {value: 66, step: 1, label: "PAM mínima (mmHg), modificable"})
viewof wAdh = Inputs.range([0.3, 1], {value: 0.72, step: 0.01, label: "Adherencia al protocolo (0–1), modificable"})






















































































wi = {
  const x = {sofa: wSofa, lactate: wLact, map_min: wMap, baseline_creat: wCreat, protocol_adherence: wAdh};
  const contrib = wiFeats.map(f =&gt; ({feature: f, label: `${f} = ${+x[f].toFixed(2)}`, value: x[f], phi: wiBeta[f] * (x[f] - wiMeans[f])}));
  const base = wiBeta["(Intercept)"] + d3.sum(wiFeats, f =&gt; wiBeta[f] * wiMeans[f]);
  const logit = base + d3.sum(contrib, d =&gt; d.phi);
  const p = 1 / (1 + Math.exp(-logit));
  const changed = wiFeats.filter(f =&gt; Math.abs(x[f] - wiAoife[f]) &gt; 1e-6);
  const fixedOk = !changed.some(f =&gt; ["sofa", "lactate", "baseline_creat"].includes(f));
  const hit = p &lt; 0.25 && fixedOk;
  if (hit && window.aihs) window.aihs.complete("ch12-tryit-whatif");
  return {contrib, base, logit, p, changed, fixedOk, hit};
}
