14.4 Aprender de la experiencia: Q-learning
La iteración de valor necesita las probabilidades de transición de la Tabla 14.2. Para un paciente real, nadie las tiene. ¿Puede un agente encontrar una buena política solo actuando y observando lo que ocurre? Eso es lo que hace el aprendizaje por refuerzo sin modelo (model-free), y el Q-learning es su algoritmo clásico (Watkins y Dayan 1992).

Definición 14.8 (Q-learning) El Q-learning mantiene una tabla de estimaciones \(\hat Q(s, a)\), una para cada estado y acción, todas empezando en cero. Tras cada paso (estado \(s\), acción \(a\), recompensa \(r\), siguiente estado \(s'\)), mueve la estimación hacia un objetivo mejor informado:
\[
\hat Q(s, a) \leftarrow \hat Q(s, a) + \eta\,\Bigl[\, \underbrace{r + \gamma \max_{a'} \hat Q(s', a')}_{\text{objetivo}} - \hat Q(s, a) \,\Bigr],
\qquad(14.5)\]
donde \(\eta\) es el tamaño del paso. Las acciones suelen elegirse de forma \(\epsilon\)-voraz a partir de la tabla actual. Si todos los pares estado–acción se siguen probando y el tamaño del paso disminuye de forma adecuada, las estimaciones convergen a \(Q^*\) (Watkins y Dayan 1992; Sutton y Barto 2018, cap. 6).

Fíjate en la forma: nueva estimación = estimación antigua + paso × (objetivo − estimación antigua), como en la Ecuación 14.1. El objetivo es una versión de un paso de la ecuación de optimalidad de Bellman: la recompensa realmente recibida más el valor descontado de la mejor acción en el estado realmente alcanzado, según la estimación actual. No aparece ninguna probabilidad de transición; el entorno proporciona muestras de ellas, un paso cada vez. El \(\max\) del objetivo es lo que hace que el Q-learning sea off-policy (fuera de la política): aprende el valor de actuar de forma voraz incluso mientras explora, de modo que los pasos exploratorios no estropean lo que aprende.
Un paso resuelto. Supón que el agente está en “10–14, baja”, con estimaciones actuales de \(-0.4\), \(0.8\) y \(1.6\) para bajar, mantener y subir. Sube la velocidad; la glucosa baja a 6–10 (recompensa \(+1\)) y el siguiente estado es “6–10, media”, cuyas estimaciones son \(2.1\), \(2.9\) y \(1.2\). Con \(\eta = 0.1\) y \(\gamma = 0.9\), el objetivo es \(1 + 0.9 \times 2.9 = 3.61\), el error es \(3.61 - 1.6 = 2.01\) y la estimación pasa a \(1.6 + 0.1 \times 2.01 = 1.801\). Programarás este paso en la misión de abajo.

Mira cómo un agente aprende a dosificar. Cada celda es un estado del problema de juguete: franja de glucosa (filas) y velocidad de infusión (columnas). La flecha muestra la acción que el agente considera mejor en este momento (← bajar, • mantener, → subir); el color muestra cuánto espera acumular el agente desde ese estado (azul es bueno, rojo es malo). El contorno grueso marca dónde está ahora la paciente simulada. Pulsa Un paso unas cuantas veces y lee la actualización que aparece debajo: es la Ecuación 14.5 con números. Después entrena durante cientos de episodios (un episodio son 24 horas: 12 pasos desde un estado inicial aleatorio). Un ✓ marca un estado en el que la elección del agente es tan buena como la de la política óptima de la Tabla 14.3 (con una tolerancia de 0,05). Objetivo: al menos 18 de los 20 estados con ✓ después de 50 o más episodios. Después pon ε en 0 y reinicia: ¿qué ocurre sin exploración?

mdpSpec = FileAttachment("data/precomputed/ch14/insulin_mdp.json").json()







mdp = {
  const M = mdpSpec.moves, gamma = mdpSpec.gamma, S = 20, A = 3;
  const sid = (g, r) =&gt; r * 5 + g, band = s =&gt; s % 5, rate = s =&gt; Math.floor(s / 5);
  const bandLab = ["&lt; 4", "4–6", "6–10", "10–14", "&gt; 14"], rateLab = ["apagada", "baja", "media", "alta"];
  function next(s, a, rew) {                 // a: 0 bajar, 1 mantener, 2 subir
    const r2 = Math.min(3, Math.max(0, rate(s) + a - 1)), g = band(s), out = [];
    for (let m = 0; m &lt; 3; m++) { const g2 = Math.min(4, Math.max(0, g + m - 1)); out.push([M[r2][m], sid(g2, r2), rew[g2]]); }
    return out;
  }
  function solve(rew) {
    let V = new Array(S).fill(0), Q = null;
    for (let k = 0; k &lt; 3000; k++) {
      Q = d3.range(S).map(s =&gt; d3.range(A).map(a =&gt; d3.sum(next(s, a, rew), ([p, s2, r]) =&gt; p * (r + gamma * V[s2]))));
      const V2 = Q.map(q =&gt; Math.max(...q)), diff = d3.max(V2, (v, i) =&gt; Math.abs(v - V[i]));
      V = V2; if (diff &lt; 1e-10) break;
    }
    const policy = Q.map(q =&gt; q.indexOf(Math.max(...q)));
    return {V, Q, policy};
  }
  function evaluate(policy) {                // ocupación exacta en 24 horas desde glucosa 10-14, infusión apagada
    let d = new Array(S).fill(0); d[sid(3, 0)] = 1; const acc = {inRange: 0, hypo: 0, hyper: 0};
    for (let t = 0; t &lt; 12; t++) {
      const d2 = new Array(S).fill(0);
      for (let s = 0; s &lt; S; s++) if (d[s] &gt; 0) for (const [p, s2] of next(s, policy[s], [0, 0, 0, 0, 0])) d2[s2] += d[s] * p;
      d = d2;
      for (let s = 0; s &lt; S; s++) { const g = band(s); if (g === 2) acc.inRange += d[s] / 12; if (g === 0) acc.hypo += d[s] / 12; if (g &gt;= 3) acc.hyper += d[s] / 12; }
    }
    return acc;
  }
  const arrows = ["←", "•", "→"];
  // Con la infusión 'apagada', bajar no cambia nada, y a la 'alta' subir tampoco: se muestran como 'mantener'.
  const eff = (s, a) =&gt; (rate(s) === 0 && a === 0) || (rate(s) === 3 && a === 2) ? 1 : a;
  // Dibuja la cuadrícula 5 x 4 de estados. cellFn(s) -&gt; {fill, label, corner, current, faded}
  function grid(cellFn, aria) {
    const cw = 104, ch = 58, x0 = 92, y0 = 44, W = x0 + 4 * cw + 12, H = y0 + 5 * ch + 34;
    const svg = d3.create("svg").attr("viewBox", `0 0 ${W} ${H}`).attr("class", "aihs-svg")
      .attr("role", "img").attr("aria-label", aria).style("max-width", "560px");
    rateLab.forEach((r, j) =&gt; svg.append("text").attr("x", x0 + j * cw + cw / 2).attr("y", y0 - 10).attr("text-anchor", "middle").attr("font-size", 13).text(r));
    svg.append("text").attr("x", x0 + 2 * cw).attr("y", 14).attr("text-anchor", "middle").attr("font-size", 13).attr("font-weight", 700).text("Velocidad de infusión de insulina →");
    for (let g = 4; g &gt;= 0; g--) {
      const row = 4 - g;
      svg.append("text").attr("x", x0 - 8).attr("y", y0 + row * ch + ch / 2 + 4).attr("text-anchor", "end").attr("font-size", 13)
        .attr("font-weight", g === 2 ? 700 : 400).text(bandLab[g] + (g === 2 ? " ★" : ""));
      for (let r = 0; r &lt; 4; r++) {
        const s = sid(g, r), c = cellFn(s), x = x0 + r * cw, y = y0 + row * ch;
        svg.append("rect").attr("x", x + 2).attr("y", y + 2).attr("width", cw - 4).attr("height", ch - 4).attr("rx", 6)
          .attr("fill", c.fill).style("stroke", c.current ? "var(--aihs-accent, #1f6f8b)" : "currentColor")
          .attr("stroke-width", c.current ? 4 : 0.6).attr("opacity", c.faded ? 0.55 : 1);
        svg.append("text").attr("x", x + cw / 2).attr("y", y + ch / 2 + 8).attr("text-anchor", "middle").attr("font-size", 24)
          .attr("font-weight", 700).style("fill", "#111").text(c.label);
        if (c.corner) svg.append("text").attr("x", x + cw - 9).attr("y", y + 17).attr("text-anchor", "end").attr("font-size", 12).style("fill", "#111").text(c.corner);
        if (c.left) svg.append("text").attr("x", x + 9).attr("y", y + 17).attr("font-size", 11).style("fill", "#333").text(c.left);
      }
    }
    svg.append("text").attr("x", 8).attr("y", y0 + 5 * ch + 24).attr("font-size", 12).attr("class", "muted").text("Filas: glucosa (mmol/L), ★ = rango objetivo.");
    return svg.node();
  }
  const colour = d3.scaleLinear().domain([-12, 0, 5]).range(["#e8a39b", "#f2f2f2", "#8fc1d4"]).clamp(true);
  return {S, A, sid, band, rate, bandLab, rateLab, next, solve, evaluate, arrows, eff, grid, colour, gamma};
}







