negData = FileAttachment("data/negation_sentences.csv").csv({typed: true})
negRules = ({
  pre: ["no evidence of", "negative for", "absence of", "rule out", "denies", "denied", "without", "not", "no"],
  post: ["was ruled out", "ruled out", "is absent", "excluded"],
  pseudo: ["no increase", "no change", "not only", "no further"],
  term: ["but", "however", "although", "except", ";"]
})
negTok = s =&gt; (String(s).toLowerCase().match(/[a-z0-9]+|;/g) || [])
negFind = (tok, phrase, start = 0) =&gt; {
  const p = String(phrase).toLowerCase().split(/\s+/).filter(x =&gt; x);
  if (!p.length) return -1;
  for (let i = start; i &lt;= tok.length - p.length; i++) {
    let ok = true;
    for (let j = 0; j &lt; p.length; j++) if (tok[i + j] !== p[j]) { ok = false; break; }
    if (ok) return i;
  }
  return -1;
}
negex = (sentence, finding, win, usePseudo, useTerm, usePost) =&gt; {
  const tok = negTok(sentence), ts = negFind(tok, finding);
  if (ts &lt; 0) return {status: "not found", tok, ts, te: -1, trig: null};
  const te = ts + String(finding).trim().split(/\s+/).length - 1;
  const blocked = (a, b) =&gt; useTerm && tok.slice(a, b).some(x =&gt; negRules.term.includes(x));
  let i = 0;
  while (i &lt; ts) {
    if (usePseudo && negRules.pseudo.some(q =&gt; negFind(tok.slice(i), q) === 0)) { i += 2; continue; }
    const hit = negRules.pre.find(t =&gt; negFind(tok.slice(i), t) === 0);
    if (hit) {
      const e = i + hit.split(" ").length - 1;
      if (e &lt; ts && ts - e &lt;= win && !blocked(e + 1, ts)) return {status: "negated", tok, ts, te, trig: [i, e]};
      i = e + 1; continue;
    }
    i++;
  }
  if (usePost) for (const t of negRules.post) {
    const s = negFind(tok, t, te + 1);
    if (s &gt; te && s - te &lt;= win && !blocked(te + 1, s)) return {status: "negated", tok, ts, te, trig: [s, s + t.split(" ").length - 1]};
  }
  return {status: "affirmed", tok, ts, te, trig: null};
}
