tDist = {
  const c = nlm.contexts.find(d =&gt; d.context === tCtx);
  const z = c.logits.map(v =&gt; v / tTau), m = d3.max(z);
  let p = z.map(v =&gt; Math.exp(v - m)); const s = d3.sum(p); p = p.map(v =&gt; v / s);
  const order = d3.range(p.length).sort((a, b) =&gt; p[b] - p[a]);
  const keep = new Set(order.slice(0, tK));
  let q = p.map((v, i) =&gt; keep.has(i) ? v : 0); const s2 = d3.sum(q); q = q.map(v =&gt; v / s2);
  const H = -d3.sum(q, v =&gt; v &gt; 0 ? v * Math.log2(v) : 0);
  const rows = order.slice(0, 12).map(i =&gt; ({token: c.tokens[i], p: q[i]}));
  return {q, tokens: c.tokens, H, eff: Math.pow(2, H), rows};
}
