function gaussNoise(seed, n) {
  let s = seed &gt;&gt;&gt; 0;
  const rnd = () =&gt; { s = (s + 0x6D2B79F5) | 0; let t = Math.imul(s ^ s &gt;&gt;&gt; 15, 1 | s); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; };
  const out = new Float64Array(n);
  for (let i = 0; i &lt; n; i++) { let u = 0; while (u === 0) u = rnd(); out[i] = Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rnd()); }
  return out;
}
